#!/usr/bin/env node
/**
 * Generates TypeScript types from the OpenAPI specs published by Cardápio Web.
 * Output: src/integrations/cardapio-web/generated/*.ts (do not edit by hand).
 * Spec list: https://docs.cardapioweb.com/llms.txt
 *
 * Uses the openapi-typescript Node API directly, so it runs the same way on Windows, macOS and Linux.
 *
 * Usage: pnpm cw:types
 */
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const ROOT_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUTPUT_DIR = path.join(ROOT_DIR, "src/integrations/cardapio-web/generated");
const SPEC_BASE_URL = "https://docs.cardapioweb.com/reference";

/** CW spec file name → English output name. */
const SPECS = {
  "api-autenticacao": "auth",
  "api-identidade": "identity",
  "api-loja": "store",
  "api-pedidos": "orders",
};

const HEADER = `/**
 * This file was auto-generated by scripts/generate-cw-types.mjs from the Cardápio Web OpenAPI specs.
 * Do not make direct changes to the file. Run \`pnpm cw:types\` instead.
 */

`;

async function main() {
  await mkdir(OUTPUT_DIR, { recursive: true });
  for (const [spec, name] of Object.entries(SPECS)) {
    const output = path.join(OUTPUT_DIR, `${name}.ts`);
    const ast = await openapiTS(new URL(`${SPEC_BASE_URL}/${spec}.json`));
    await writeFile(output, HEADER + astToString(ast));
    console.log(`Generated ${path.relative(ROOT_DIR, output)}`);
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
